import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String raw_input_str = scanner.nextLine();
        String middle_part = raw_input_str.substring(1, raw_input_str.length() - 1);
        int length_middle = middle_part.length();
        StringBuilder output_string = new StringBuilder();
        output_string.append(raw_input_str.charAt(0));
        int index_counter = 0;
        boolean has_found_at = false;
        while (index_counter < length_middle) {
            if (index_counter + 3 <= length_middle) {
                if (middle_part.substring(index_counter, index_counter + 3).equals("dot")) {
                    output_string.append(".");
                    index_counter += 3;
                    continue;
                }
            }
            if (index_counter + 2 <= length_middle && !has_found_at) {
                if (middle_part.substring(index_counter, index_counter + 2).equals("at")) {
                    output_string.append("@");
                    has_found_at = true;
                    index_counter += 2;
                    continue;
                }
            }
            output_string.append(middle_part.charAt(index_counter));
            index_counter++;
        }
        output_string.append(raw_input_str.charAt(raw_input_str.length() - 1));
        System.out.println(output_string.toString());
        scanner.close();
    }
}
